import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();
        solve(n, mod);
        scanner.close();
    }

    public static void solve(int n, int mod) {
        if (n <= 3) {
            System.out.println(0);
            return;
        }
        long prev_ans = 17;
        long current_ans = 17;
        int max_len = (n - 1) * (n - 2) / 2 + 1;
        int flip = 1;
        long[][] dp_record = new long[2][max_len + 1];
        // Initialize dp_record[0][0..3]
        dp_record[0][0] = 1;
        dp_record[0][1] = 2;
        dp_record[0][2] = 2;
        dp_record[0][3] = 1;

        for (int m = 4; m < n; m++) {
            int pair_count = m * (m - 1) / 2;
            current_ans = (m + 1) * prev_ans;
            long cum_sum = 0;
            // Compute dp_record[flip][i] for i in [0, m-1]
            for (int i = 0; i < m; i++) {
                cum_sum += dp_record[flip ^ 1][i];
                dp_record[flip][i] = cum_sum % mod;
            }
            // Compute for i in [m, pair_count/2]
            for (int i = m; i <= pair_count / 2; i++) {
                cum_sum += dp_record[flip ^ 1][i];
                cum_sum -= dp_record[flip ^ 1][i - m];
                dp_record[flip][i] = cum_sum % mod;
            }
            // Mirror the values for symmetry
            for (int i = 0; i <= pair_count / 2; i++) {
                dp_record[flip][pair_count - i] = dp_record[flip][i];
            }
            long total_sum = 0;
            for (int i = 0; i < pair_count; i++) {
                long temp_total = 0;
                int start_idx = Math.max(1, -pair_count + i + m + 2);
                for (int j = start_idx; j <= m; j++) {
                    int index = m + 2 - j + i;
                    if (index >= 0 && index <= pair_count) {
                        temp_total += j * dp_record[flip][index];
                    }
                }
                total_sum += dp_record[flip][i];
                total_sum %= mod;
                temp_total %= mod;
                current_ans += (temp_total * total_sum) % mod;
                current_ans %= mod;
            }
            prev_ans = current_ans;
            flip ^= 1;
        }
        System.out.println(current_ans % mod);
    }
}
